# Builds assets/icons.js for both directions from the icon sets (only the glyphs the screens use).
#   npm install @material-symbols/svg-400@0.27.0 @phosphor-icons/core@2.1.1   (Apache-2.0, MIT) next to this script
#   python3 build_icons.py <phoenix-material>/assets/icons.js <ember>/assets/icons.js
import json, os, re, sys
NM = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'node_modules')
def inner(svg):
    m = re.search(r'<svg[^>]*viewBox="([^"]+)"[^>]*>(.*)</svg>', svg, re.S)
    return m.group(1), m.group(2)
def build(kind, names, out):
    icons = {}
    for alias, src in names.items():
        if kind == 'ms':
            p = f'{NM}/@material-symbols/svg-400/rounded/{src}.svg'
        else:
            w = 'light'
            s = src
            if ':' in src: s, w = src.split(':')
            p = f'{NM}/@phosphor-icons/core/assets/{w}/{s}{"" if w=="regular" else "-"+w}.svg'
        if not os.path.exists(p):
            print('MISSING', alias, p); continue
        vb, body = inner(open(p).read())
        icons[alias] = [vb, body]
    if kind == 'ms':
        sp = '<path d="M480-880q18 190 104 296t296 104q-210 18-296 104T480-80q-18-210-104-296T80-480q210-18 296-104t104-296Z"/>'
        icons['spark'] = ['0 -960 960 960', sp]
        icons['spark-fill'] = ['0 -960 960 960', sp]
    js = '/* Icons: ' + ('Material Symbols Rounded (Apache-2.0, google/material-design-icons)' if kind=='ms' else 'Phosphor Icons, light and thin weights (MIT, phosphor-icons/core)') + '. Generated by a script from the npm package; only the glyphs these screens use. */\n'
    js += 'window.ICONS = ' + json.dumps(icons, separators=(',',':')) + ';\n'
    open(out, 'w').write(js)
    print(out, len(icons), os.path.getsize(out))

ms = {}
for n in """search mic more_vert more_horiz edit add send attach_file mood arrow_back chevron_right chevron_left keyboard_arrow_down wifi bluetooth flight vpn_key wallpaper palette light_mode dark_mode volume_up battery_full battery_5_bar keyboard location_on lock info call chat chat_bubble forum mail inbox calendar_month music_note photo_library person group settings star flag archive delete reply reply_all forward folder draft play_arrow pause skip_next skip_previous shuffle repeat favorite queue_music lyrics headphones check close notifications signal_cellular_4_bar photo_camera sms alternate_email today label attachment picture_as_pdf description table_chart done_all schedule add_circle verified link sync cloud devices smartphone security accessibility_new language event work cake restaurant pool medical_services groups videocam content_copy tune filter_list image apps home bolt brightness_6 screen_lock_portrait speaker swap_horiz drag_indicator mark_email_unread task_alt public edit_square local_florist""".split():
    ms[n] = n
for n in ['skip_next','skip_previous','drag_indicator','add_circle','alternate_email','attach_file','reply','reply_all','forward','chevron_right','tune','filter_list','apps','bolt','public','link','cloud','sync','content_copy','chat','sms','group','event','work','cake','lock','location_on','palette','wallpaper','volume_up','folder','draft','send','archive','delete','label','today','description','picture_as_pdf','table_chart','restaurant','pool','medical_services','local_florist','headphones','queue_music','lyrics','speaker','vpn_key','brightness_6','keyboard','info','security','accessibility_new','language','devices','smartphone','screen_lock_portrait','videocam','photo_camera','task_alt','mark_email_unread','star','flag','favorite','check_circle','play_arrow','pause','chat_bubble','mail','person','settings','calendar_month','music_note','photo_library','call','inbox','forum','notifications','home','wifi','bluetooth','flight','light_mode','push_pin','circle','verified','schedule','edit','image','groups']:
    ms[n+'-fill'] = n+'-fill'
ms['keep']='keep'
build('ms', ms, sys.argv[1])

